using CertDesk.Common; using CertDesk.Services;
namespace CertDesk.Forms;
public partial class TokenIssueForm:Form { ComboBox emp=new(){Width=250,DropDownStyle=ComboBoxStyle.DropDownList}; TextBox act=new(){Width=250}, comment=new(){Width=250}; public int EmployeeId=>((ComboBoxItem)emp.SelectedItem).Id!.Value; public string ActNumber=>act.Text; public string Comment=>comment.Text; public TokenIssueForm(){InitializeComponent(); Controls.AddRange(new Control[]{new Label{Text="Сотрудник",Left=20,Top=25},emp,new Label{Text="Номер акта",Left=20,Top=65},act,new Label{Text="Комментарий",Left=20,Top=105},comment}); emp.Left=140;emp.Top=20; act.Left=140;act.Top=60;comment.Left=140;comment.Top=100; foreach(var e in EmployeeService.GetActive()) emp.Items.Add(new ComboBoxItem{Id=e.Id,Text=e.FullName}); if(emp.Items.Count>0) emp.SelectedIndex=0; var ok=new Button{Text="Сохранить",Left=140,Top=145}; var cancel=new Button{Text="Отмена",Left=260,Top=145,DialogResult=DialogResult.Cancel}; UiTheme.ApplyButtonStyle(ok); Controls.AddRange(new Control[]{ok,cancel}); ok.Click+=(_,__)=>{ if(emp.SelectedItem==null) MessageHelper.Error("Выберите сотрудника"); else DialogResult=DialogResult.OK;}; } }
